insert into fund_profile (id, sector_focus, stages, check_size_min, check_size_max, check_size_flex_note, investment_lens) values (1, 'Oncology-focused healthtech & digital health', 'Seed – Series A (sometimes Series B)', 5, 15, 'can flex up to +5 / down to -2', 'Trace the actual chain of effect: how could this affect a cancer patient — or someone who might eventually become one — either in care delivery or in getting a life-changing drug/therapy to market faster? Think in hops, not just direct oncology products. E.g. routine PCP tools affect screening/early diagnosis timing; specialty pharmacy and prior-auth tools gate access to extremely expensive cancer drugs even though they don''t look oncology-specific on the surface. Score the strength of that chain honestly (direct vs. multi-hop/diffuse) rather than requiring the company to say ''oncology'' anywhere in its pitch.');
